// n8n Code sandbox не даёт global fetch и не пускает require без
// NODE_FUNCTION_ALLOW_BUILTIN. Мы разрешили crypto,http,https и используем
// node:https через самодельный fetch-shim.
const crypto = require('crypto');
const https = require('node:https');
const http_ = require('node:http');
const { URL } = require('node:url');

function fetch(url, opts = {}) {
  const u = new URL(url);
  const isHttps = u.protocol === 'https:';
  const bodyStr = opts.body != null ? (typeof opts.body === 'string' ? opts.body : JSON.stringify(opts.body)) : null;
  const headers = Object.assign({}, opts.headers || {});
  if (bodyStr != null) headers['content-length'] = Buffer.byteLength(bodyStr);
  const options = {
    method: opts.method || 'GET',
    hostname: u.hostname,
    port: u.port || (isHttps ? 443 : 80),
    path: u.pathname + u.search,
    headers,
  };
  return new Promise((resolve, reject) => {
    const req = (isHttps ? https : http_).request(options, res => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        const text = Buffer.concat(chunks).toString('utf8');
        resolve({
          ok: res.statusCode >= 200 && res.statusCode < 300,
          status: res.statusCode,
          headers: res.headers,
          text: async () => text,
          json: async () => JSON.parse(text),
        });
      });
    });
    req.on('error', reject);
    if (bodyStr != null) req.write(bodyStr);
    req.end();
  });
}

// 1. Проверка HMAC подписи от бэкенда.
const input = $input.first().json;
const headers = input.headers || {};
const rawBody = input.body || '';
const signature = headers['x-signature'] || '';
const timestamp = Number(headers['x-signature-timestamp'] || 0);
const secret = ($env.AI_SUPPORT_HMAC_SECRET ?? $env.WEBHOOK_SECRET);
if (!secret) throw new Error('AI_SUPPORT_HMAC_SECRET (или WEBHOOK_SECRET) не задан в env');
if (Math.abs(Math.floor(Date.now() / 1000) - timestamp) > 300)
  throw new Error('signature timestamp expired');
const rawStr = typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody);
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${rawStr}`).digest('hex');
if (signature !== expected) throw new Error('signature mismatch');

const payload = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
const ticket = payload.ticket;
const apiUrl = (($env.BACKEND_API_URL ?? $env.SKLADPRO_API_URL) || '').replace(/\/+$/, '');
const repo = ($env.TARGET_REPO ?? $env.SKLADPRO_REPO);

async function patchTicket(patchBody) {
  const body = JSON.stringify(patchBody);
  const ts = Math.floor(Date.now() / 1000);
  const sig = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${body}`).digest('hex');
  try {
    await fetch(`${apiUrl}/v1/support/tickets/${encodeURIComponent(ticket.id)}`, {
      method: 'PATCH',
      headers: {
        'content-type': 'application/json',
        'x-signature-timestamp': String(ts),
        'x-signature': sig,
      },
      body,
    });
  } catch (err) {
    // Callback — best-effort: если бэкенд лежит, workflow всё равно доделает работу.
  }
}

await patchTicket({ status: 'analyzing' });

const gh = async (method, path, json) => {
  const res = await fetch(`https://api.github.com${path}`, {
    method,
    headers: {
      Authorization: `Bearer ${$env.GITHUB_PAT}`,
      Accept: 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28',
      'User-Agent': 'ai-support-bot',
      ...(json ? { 'content-type': 'application/json' } : {}),
    },
    body: json ? JSON.stringify(json) : undefined,
  });
  if (!res.ok) throw new Error(`GitHub ${method} ${path}: ${res.status} ${(await res.text()).slice(0,300)}`);
  return res.json();
};

const repoInfo = await gh('GET', `/repos/${repo}`);
const defaultBranch = repoInfo.default_branch;
const branchInfo = await gh('GET', `/repos/${repo}/branches/${defaultBranch}`);
const baseSha = branchInfo.commit.sha;
const baseTreeSha = branchInfo.commit.commit.tree.sha;
const tree = await gh('GET', `/repos/${repo}/git/trees/${baseTreeSha}?recursive=1`);
const includeRe = new RegExp($env.REPO_FILE_INCLUDE || '^(src|scripts)/.*\\.(js|jsx|ts|tsx|css)$');
const codeFiles = tree.tree
  .filter(t => t.type === 'blob' && includeRe.test(t.path))
  .map(t => t.path);

const tools = [
  { type: 'function', function: { name: 'read_file',
    description: 'Прочитать файл из репозитория.',
    parameters: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'] } } },
  { type: 'function', function: { name: 'submit_fix',
    description: 'Финализировать исправление одного файла.',
    parameters: { type: 'object', properties: {
      file_path: { type: 'string' }, new_content: { type: 'string' },
      explanation: { type: 'string' }, commit_message: { type: 'string' }
    }, required: ['file_path', 'new_content', 'explanation', 'commit_message'] } } },
  { type: 'function', function: { name: 'give_up',
    description: 'Признать недостаток данных.',
    parameters: { type: 'object', properties: { reason: { type: 'string' } }, required: ['reason'] } } },
];

async function callTool(name, args) {
  if (name === 'read_file') {
    const path = args.path;
    if (!codeFiles.includes(path)) return { error: `File ${path} not in allowed list` };
    const r = await gh('GET', `/repos/${repo}/contents/${encodeURIComponent(path)}?ref=${defaultBranch}`);
    const content = Buffer.from(r.content, 'base64').toString('utf8');
    const maxBytes = Number($env.REPO_FILE_MAX_BYTES) || 30000;
    return { path, content: content.length > maxBytes ? content.slice(0, maxBytes) + '\n… (truncated)' : content };
  }
  return null;
}

const stackDescr = $env.AI_STACK_DESCRIPTION || 'React + Vite + Zustand, JavaScript без TS';
const systemPrompt = `Ты — автономный старший разработчик проекта (стек: ${stackDescr}).\nТебе прислали жалобу клиента и структуру репозитория. Задача:\n1) Локализовать баг (используй read_file, начиная с самых вероятных страниц).\n2) Найти причину.\n3) Вызвать submit_fix с ПОЛНЫМ обновлённым содержимым файла и коротким объяснением.\n\nОграничения:\n- Один файл в исходниках. Не трогай package.json, миграции, .env, тесты.\n- Не выдумывай API — если функция незнакома, читай файл, где она определена.\n- Не пиши комментарии типа "fixed the bug".\n- Если данных мало — вызови give_up с внятной причиной.\n\nЖалоба клиента:\n"""\n${ticket.description}\n"""\n\nСтраница: ${ticket.pageUrl || 'н/д'} — ${ticket.pageTitle || ''}\nUser-Agent: ${ticket.userAgent || 'н/д'}\nКонтекст: ${JSON.stringify(ticket.context || {})}\n\nФайлы в репо:\n${codeFiles.join('\n')}`;

const messages = [{ role: 'system', content: systemPrompt }];
let finalFix = null;
let gaveUp = null;
const MAX_ITER = Number($env.AI_MAX_ITER) || 12;
const llmModel = $env.AI_MODEL || 'gpt-4o-mini';
const llmTemperature = Number($env.AI_TEMPERATURE) || 0.2;
const llmBase = (($env.AI_LLM_BASE_URL ?? $env.DEEPSEEK_BASE_URL) || 'https://api.deepseek.com/v1').replace(/\/+$/, '');

for (let i = 0; i < MAX_ITER && !finalFix && !gaveUp; i++) {
  const res = await fetch(llmBase + '/chat/completions', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${($env.AI_LLM_API_KEY ?? $env.DEEPSEEK_API_KEY)}`,
      'content-type': 'application/json',
    },
    body: JSON.stringify({
      model: llmModel,
      messages, tools, tool_choice: 'auto', temperature: llmTemperature,
    }),
  });
  if (!res.ok) throw new Error(`LLM ${res.status}: ${(await res.text()).slice(0,500)}`);
  const j = await res.json();
  const msg = j.choices[0].message;
  messages.push(msg);
  const calls = msg.tool_calls || [];
  if (calls.length === 0) break;
  for (const c of calls) {
    const args = JSON.parse(c.function.arguments || '{}');
    if (c.function.name === 'submit_fix') { finalFix = args; break; }
    if (c.function.name === 'give_up') { gaveUp = args.reason; break; }
    const result = await callTool(c.function.name, args);
    messages.push({ role: 'tool', tool_call_id: c.id, content: JSON.stringify(result) });
  }
}

if (!finalFix) {
  const reason = gaveUp || 'LLM исчерпал итерации и не нашёл файл для фикса';
  await patchTicket({ status: 'failed', aiExplanation: reason });
  return [{ json: {
    ok: false,
    ticket,
    ticketId: ticket.id,
    prNumber: 0,
    prUrl: '(PR не создан — AI не нашёл причину)',
    branchName: '',
    aiExplanation: reason,
    aiFilePath: '',
  } }];
}

const branchPrefix = $env.BRANCH_PREFIX || 'fix/ai-';
const branch = `${branchPrefix}${ticket.id.slice(0, 8)}`;
await gh('POST', `/repos/${repo}/git/refs`, { ref: `refs/heads/${branch}`, sha: baseSha });

let currentSha = null;
try {
  const existing = await gh('GET', `/repos/${repo}/contents/${encodeURIComponent(finalFix.file_path)}?ref=${defaultBranch}`);
  currentSha = existing.sha;
} catch (_) {}

await gh('PUT', `/repos/${repo}/contents/${encodeURIComponent(finalFix.file_path)}`, {
  message: finalFix.commit_message,
  content: Buffer.from(finalFix.new_content, 'utf8').toString('base64'),
  branch,
  ...(currentSha ? { sha: currentSha } : {}),
});

const pr = await gh('POST', `/repos/${repo}/pulls`, {
  title: finalFix.commit_message,
  head: branch,
  base: defaultBranch,
  body: `Автоматически создано n8n по обращению клиента #${ticket.id}.\n\n**Жалоба клиента:**\n> ${ticket.description.replace(/\n/g, '\n> ')}\n\n**Объяснение:**\n${finalFix.explanation}\n\n**Страница:** ${ticket.pageUrl || 'н/д'}`,
});

await patchTicket({
  status: 'pr_open',
  prUrl: pr.html_url,
  prNumber: pr.number,
  branchName: branch,
  aiExplanation: finalFix.explanation,
  aiFilePath: finalFix.file_path,
});

// Telegram sendMessage сразу отсюда — так безопаснее escape'ится через
// JSON.stringify, чем через шаблонизатор в HTTP Request ноде.
const tgTitle = $env.TG_MESSAGE_TITLE || '🛎 Новый тикет';
const tgText = [
  `<b>${tgTitle}</b>`,
  '',
  '<b>Клиент:</b> ' + ticket.userId,
  '<b>Страница:</b> ' + (ticket.pageUrl || 'н/д'),
  '',
  '<b>Жалоба:</b>',
  String(ticket.description).slice(0, 1500),
  '',
  '<b>Причина (AI):</b>',
  String(finalFix.explanation).slice(0, 1500),
  '',
  '<b>Файл:</b> <code>' + finalFix.file_path + '</code>',
  '<b>PR:</b> ' + pr.html_url,
].join('\n')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  // возвращаем разрешённые HTML-теги обратно
  .replace(/&lt;(\/?b)&gt;/g, '<$1>')
  .replace(/&lt;(\/?code)&gt;/g, '<$1>');

try {
  await fetch(`https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/sendMessage`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({
      chat_id: Number($env.TELEGRAM_CHAT_ID),
      parse_mode: 'HTML',
      text: tgText,
      reply_markup: {
        inline_keyboard: [[
          { text: '✅ Одобрить и смержить', callback_data: `approve:${ticket.id}:${pr.number}` },
          { text: '❌ Отклонить',           callback_data: `reject:${ticket.id}:${pr.number}` },
        ]],
      },
    }),
  });
} catch (err) {
  // Не роняем весь workflow из-за Telegram — тикет в БД уже помечен pr_open.
}

return [{ json: {
  ok: true,
  ticketId: ticket.id,
  prNumber: pr.number,
  prUrl: pr.html_url,
  branchName: branch,
  aiExplanation: finalFix.explanation,
  aiFilePath: finalFix.file_path,
  ticket,
}}];
